import 'dart:async';

import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../debug/application/debug_devices_controller.dart';
import '../../application/macro_runtime_session_controller.dart';

/// Presentation contract for one independently implemented macro node family.
///
/// The macro editor only uses this contract. A concrete trigger, modifier or
/// sink owns its palette metadata, node construction and Flutter rendering;
/// it must not import another concrete node family. The presentation registry
/// is the one composition root that is allowed to install multiple modules.
abstract base class MacroEditorNodeModule {
  const MacroEditorNodeModule();

  /// Stable macro-node kind handled by this presentation module.
  String get kind;

  /// Returns whether this module can render and edit [node].
  bool supports(MacroNode node) => node.kind == kind;

  /// User-facing title for the plot card and inspector.
  String titleFor(MacroNode node) => node.displayName ?? kind;

  /// Entries this module contributes to the palette for the current editor.
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => const <MacroEditorPaletteEntry>[];

  /// Creates one persisted graph node from a palette entry, or returns null
  /// when its ephemeral payload is no longer valid (for example a disconnected
  /// device whose capability profile disappeared).
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => null;

  /// Reserved plot-card height for [buildCardBody].
  double cardBodyHeight(MacroNode node) => 0;

  /// Optional compact interactive content rendered inside a plot card.
  Widget? buildCardBody(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => null;

  /// Full inspector content for a selected node.
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => MacroEditorNodeInspectorCard(
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
  );
}

/// A module that contributes a target-binding representation to a graph.
///
/// This keeps persistence migration and graph-edge-to-binding mapping with the
/// target-node implementation, rather than making the editor branch on a sink
/// kind.
abstract interface class MacroEditorBindingModule {
  Iterable<MacroTargetBinding> deriveTargetBindings(MacroGraph graph);

  MacroGraph migrateLegacyBindings(
    MacroGraph graph, {
    required MacroEditorNewId newId,
  });
}

/// A module eligible for the default starter graph.
///
/// The registry connects the declared starter source and processor only by
/// their public ports; neither module imports or names the other.
abstract interface class MacroEditorStarterNodeModule {
  MacroEditorStarterRole get starterRole;

  MacroNode createStarterNode({required MacroEditorNewId newId});
}

enum MacroEditorStarterRole { source, processor }

typedef MacroEditorNewId = String Function();

enum MacroEditorPaletteSection { modules, devices }

/// A presentation-only palette item. [payload] is never persisted; it may
/// carry a currently discovered device for a target-node module.
final class MacroEditorPaletteEntry {
  const MacroEditorPaletteEntry({
    required this.id,
    required this.moduleKind,
    required this.section,
    required this.icon,
    required this.title,
    required this.subtitle,
    this.enabled = true,
    this.payload,
  });

  final String id;
  final String moduleKind;
  final MacroEditorPaletteSection section;
  final IconData icon;
  final String title;
  final String subtitle;
  final bool enabled;
  final Object? payload;
}

/// Read-only data available to all node presentation modules for one build.
final class MacroEditorNodePresentationState {
  MacroEditorNodePresentationState({
    required this.graph,
    required this.enabled,
    required Map<String, DebugDevice> devicesById,
    required Iterable<DebugDevice> devices,
    this.runtime,
    this.runtimeFrames,
  }) : devicesById = Map<String, DebugDevice>.unmodifiable(devicesById),
       devices = List<DebugDevice>.unmodifiable(devices);

  final MacroGraph graph;
  final bool enabled;
  final Map<String, DebugDevice> devicesById;
  final List<DebugDevice> devices;
  final MacroRuntimeSessionStatus? runtime;

  /// Opaque, unbuffered runtime frames for the currently running macro.
  /// Concrete modules may opt in and interpret only their own frame types; the
  /// generic editor never interprets the payload.
  final Stream<Object>? runtimeFrames;
}

/// A selected node plus generic graph-mutation callbacks owned by the editor.
///
/// A module may replace only its supplied [node] or request its removal. It
/// cannot mutate editor state, transport state, or another module directly.
final class MacroEditorNodeViewContext {
  const MacroEditorNodeViewContext({
    required this.node,
    required this.state,
    required this.replaceNode,
    required this.removeNode,
  });

  final MacroNode node;
  final MacroEditorNodePresentationState state;
  final ValueChanged<MacroNode> replaceNode;
  final VoidCallback removeNode;
}

/// Shared framing for the majority of simple node inspectors.
class MacroEditorNodeInspectorCard extends StatelessWidget {
  const MacroEditorNodeInspectorCard({
    super.key,
    required this.title,
    required this.enabled,
    required this.onRemove,
    this.icon,
    this.child,
  });

  final String title;
  final bool enabled;
  final VoidCallback onRemove;
  final IconData? icon;
  final Widget? child;

  @override
  Widget build(BuildContext context) => Card(
    child: Padding(
      padding: const EdgeInsets.all(12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              if (icon case final icon?) ...<Widget>[
                Icon(icon),
                const SizedBox(width: 8),
              ],
              Expanded(child: Text(title)),
              IconButton(
                tooltip: 'Видалити вузол',
                onPressed: enabled ? onRemove : null,
                icon: const Icon(Icons.delete_outline),
              ),
            ],
          ),
          if (child case final child?) ...<Widget>[
            const SizedBox(height: 8),
            child,
          ],
        ],
      ),
    ),
  );
}

class MacroEditorNodeErrorCard extends StatelessWidget {
  const MacroEditorNodeErrorCard({super.key, required this.message});

  final String message;

  @override
  Widget build(BuildContext context) => Card(
    color: Theme.of(context).colorScheme.errorContainer,
    child: Padding(padding: const EdgeInsets.all(12), child: Text(message)),
  );
}
